import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';

const root = new URL('../', import.meta.url);
const directory = new URL('public/images/ui-icons/', root);
const lists = new URL('output/missing-images/', root);
const output = new URL('src/data/ui-icons.js', root);
mkdirSync(directory, { recursive: true });

const files = readdirSync(directory).filter((file) => /^[a-z0-9-]+\.webp$/.test(file)).sort();
const entries = files.map((file) => `  "${file.slice(0, -5)}": "images/ui-icons/${file}",`);
writeFileSync(output, [
  '// Generated by scripts/sync-ui-icons.mjs from public/images/ui-icons/*.webp.',
  'export const UI_ICONS = {',
  ...entries,
  '};',
  '',
].join('\n'));

for (const file of readdirSync(lists).filter((name) => /^ui-icons-.*\.jsonl$/.test(name)).sort()) {
  const rows = readFileSync(new URL(file, lists), 'utf8').split(/\r?\n/).filter((line) => line.trim());
  const keys = rows.map((line) => JSON.parse(line).key);
  const missing = keys.filter((key) => !existsSync(new URL(`${key}.webp`, directory)));
  console.log(`${file}: ${missing.join(', ') || 'aucune clé manquante'}`);
}
